solution.solution.cpp:
#include <cmath>
#include <cstdint>
#include <cstring>
#include <set>
#include <vector>

struct Changed
{
    std::uint64_t address;
    std::int32_t beforeInt, afterInt;
    float beforeFloat, afterFloat;
};

std::vector<Changed> changedDwords(const std::vector<std::uint8_t>& before, const std::vector<std::uint8_t>& after, std::uint64_t base)
{
    std::vector<Changed> out;
    for (std::size_t at{ 0 }; at + 4 <= before.size() && at + 4 <= after.size(); at += 4)
    {
        if (std::memcmp(&before[at], &after[at], 4) == 0) continue;
        Changed c{};
        c.address = base + at;
        std::memcpy(&c.beforeInt, &before[at], 4);
        std::memcpy(&c.afterInt, &after[at], 4);
        std::memcpy(&c.beforeFloat, &before[at], 4);
        std::memcpy(&c.afterFloat, &after[at], 4);
        out.push_back(c);
    }
    return out;
}

std::vector<Changed> withoutNoise(const std::vector<Changed>& changes, const std::vector<Changed>& noise)
{
    std::set<std::uint64_t> noisy;
    for (const Changed& n : noise) noisy.insert(n.address);
    std::vector<Changed> out;
    for (const Changed& c : changes) if (!noisy.count(c.address)) out.push_back(c);
    return out;
}

bool looksLikeFloat(float value)
{
    if (value == 0.0f) return true;
    if (!std::isfinite(value)) return false;
    const float a{ std::fabs(value) };
    return a >= 0.0001f && a <= 1000000.0f;
}

unitTests:
#include <cstring>
#include <limits>
using Bytes = std::vector<std::uint8_t>;
static void putF(Bytes& b, std::size_t at, float f) { std::memcpy(&b[at], &f, 4); }
static void putI(Bytes& b, std::size_t at, std::int32_t i) { std::memcpy(&b[at], &i, 4); }

TEST("the lesson's jump") {
    Bytes before(16, 0), after(16, 0);
    putF(before, 0, 100.0f); putF(after, 0, 120.0f);
    putF(before, 4, 0.0f);   putF(after, 4, 20.0f);
    putI(before, 8, 1);      putI(after, 8, 0);
    putI(before, 12, 77);    putI(after, 12, 77);
    const auto c{ changedDwords(before, after, 0x2C409610) };
    CHECK_EQ(c.size(), 3u);
    if (c.size() != 3) return;
    CHECK_EQ(c[0].address, 0x2C409610ull);
    CHECK_EQ(c[0].beforeFloat, 100.0f); CHECK_EQ(c[0].afterFloat, 120.0f);
    CHECK_EQ(c[0].beforeInt, 0x42C80000);
    CHECK_EQ(c[2].address, 0x2C409618ull);
    CHECK_EQ(c[2].beforeInt, 1); CHECK_EQ(c[2].afterInt, 0);
}
TEST("partial groups and equal snapshots") {
    const Bytes a{ 1, 2, 3, 4, 5, 6 }, b{ 1, 2, 3, 4, 9, 9 };
    CHECK(changedDwords(a, b, 0).empty());
    CHECK(changedDwords(a, a, 0).empty());
    const Bytes c{ 1, 2, 3, 5 };
    CHECK_EQ(changedDwords(Bytes{ 1, 2, 3, 4 }, c, 0x10).size(), 1u);
}
TEST("noise removed") {
    Bytes before(12, 0), after(12, 0), still(12, 0);
    putI(after, 0, 5); putI(after, 4, 9); putI(still, 4, 3);
    const auto real{ changedDwords(before, after, 0x100) };
    const auto noise{ changedDwords(before, still, 0x100) };
    const auto kept{ withoutNoise(real, noise) };
    CHECK_EQ(kept.size(), 1u);
    if (!kept.empty()) CHECK_EQ(kept[0].address, 0x100ull);
}
TEST("plausible floats") {
    CHECK(looksLikeFloat(0.0f));
    CHECK(looksLikeFloat(120.0f));
    CHECK(looksLikeFloat(-3.5f));
    CHECK(!looksLikeFloat(1e-20f));
    CHECK(!looksLikeFloat(5e9f));
    CHECK(!looksLikeFloat(std::numeric_limits<float>::infinity()));
    float fromInt;
    const std::int32_t one{ 1 };
    std::memcpy(&fromInt, &one, 4);
    CHECK(!looksLikeFloat(fromInt));
}

